package websocket // import "github.com/coder/websocket"

func Accept(w http.ResponseWriter, r *http.Request, opts *AcceptOptions) (*Conn, error)
    Accept accepts a WebSocket handshake from a client and upgrades the the
    connection to a WebSocket.

    Accept will not allow cross origin requests by default. See the
    InsecureSkipVerify and OriginPatterns options to allow cross origin
    requests.

    Accept will write a response to w on all errors.

=== AcceptOptions ===
package websocket // import "github.com/coder/websocket"

type AcceptOptions struct {
	// Subprotocols lists the WebSocket subprotocols that Accept will negotiate with the client.
	// The empty subprotocol will always be negotiated as per RFC 6455. If you would like to
	// reject it, close the connection when c.Subprotocol() == "".
	Subprotocols []string

	// InsecureSkipVerify is used to disable Accept's origin verification behaviour.
	//
	// You probably want to use OriginPatterns instead.
	InsecureSkipVerify bool

	// OriginPatterns lists the host patterns for authorized origins.
	// The request host is always authorized.
	// Use this to enable cross origin WebSockets.
	//
	// i.e javascript running on example.com wants to access a WebSocket server at chat.example.com.
	// In such a case, example.com is the origin and chat.example.com is the request host.
	// One would set this field to []string{"example.com"} to authorize example.com to connect.
=== Conn methods ===
package websocket // import "github.com/coder/websocket"

type Conn struct {
	// Has unexported fields.
}
    Conn represents a WebSocket connection. All methods may be called
    concurrently except for Reader and Read.

    You must always read from the connection. Otherwise control frames will not
    be handled. See Reader and CloseRead.

    Be sure to call Close on the connection when you are finished with it to
    release associated resources.

    On any error from any method, the connection is closed with an appropriate
    reason.

    This applies to context expirations as well unfortunately. See
    https://github.com/nhooyr/websocket/issues/242#issuecomment-633182220

func Accept(w http.ResponseWriter, r *http.Request, opts *AcceptOptions) (*Conn, error)
func Dial(ctx context.Context, u string, opts *DialOptions) (*Conn, *http.Response, error)
